import type { SuiteResult } from './bridgeProtocol';
import type { RunRecord, StepRecord } from './runs';
import { failingStep, suiteSummary } from './suite';

/**
 * Test reports from run records: JUnit XML (what CI tools read), a self-contained HTML page
 * (screenshots embedded) to send to someone, and versioned JSON for programs (schema:
 * docs/guide/report.schema.json, generated by scripts/reportSchema.ts). Suites (M4.4) get the same three
 * as one combined report: `toSuiteJUnit`, `toSuiteHtml`, `toSuiteJson` (docs/guide/suite-report.schema.json).
 */

/**
 * Version of the JSON report format. Raise it when a field changes meaning or goes away (adding
 * optional fields does not need a new version), and regenerate the schema (`npm run guide:sync`).
 */
export const REPORT_SCHEMA_VERSION = 1;
/** Where the schema is published, relative to the repository (the `$schema` of a report). */
export const REPORT_SCHEMA_PATH = 'docs/guide/report.schema.json';

/** The JSON report: `runs` are the stored run records, newest last as given. */
export interface JsonReport {
  $schema: string;
  schemaVersion: typeof REPORT_SCHEMA_VERSION;
  /** ISO time the report was made. */
  generatedAt: string;
  summary: RunSummary;
  runs: RunRecord[];
}

export interface ReportOptions {
  /** Block type → label, e.g. "assert" → "Assert". */
  blockLabel(type: string): string;
  /** Screenshot id → data URL, for the HTML report (step screenshots and M5.1 trace pictures). */
  screenshots?: Record<string, string>;
  title?: string;
}

/** Counts over a list of runs. failed includes interrupted; other = cancelled or still running. */
export interface RunSummary {
  total: number;
  passed: number;
  failed: number;
  other: number;
  durationMs: number;
}

/** Run length in ms (0 while it is still running). */
export function durationOf(run: RunRecord): number {
  return run.endedAt ? Math.max(0, Date.parse(run.endedAt) - Date.parse(run.startedAt)) : 0;
}

/** Totals for the report header and JUnit attributes. */
export function summarize(runs: RunRecord[]): RunSummary {
  return {
    total: runs.length,
    passed: runs.filter((run) => run.status === 'passed').length,
    failed: runs.filter((run) => run.status === 'failed' || run.status === 'interrupted').length,
    other: runs.filter((run) => run.status === 'cancelled' || run.status === 'running').length,
    durationMs: runs.reduce((sum, run) => sum + durationOf(run), 0),
  };
}

function xml(text: string): string {
  return text.replace(/[<>&"']/g, (char) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;', "'": '&apos;' })[char] ?? char);
}

function seconds(ms: number): string {
  return (ms / 1000).toFixed(3);
}

function stepLine(step: StepRecord, options: ReportOptions): string {
  const time = step.durationMs !== undefined ? ` (${step.durationMs} ms)` : '';
  const code = step.code ? ` [${step.code}]` : '';
  return `${step.status.padEnd(7)} ${options.blockLabel(step.blockType)}${time}${step.error ? ` — ${step.error}${code}` : ''}`;
}

/** The JSON report of `runs` (see {@link JsonReport}). `now` is the report time. */
export function toJsonReport(runs: RunRecord[], now: Date = new Date()): JsonReport {
  return {
    $schema: `https://github.com/akib35/blockflow/${REPORT_SCHEMA_PATH}`,
    schemaVersion: REPORT_SCHEMA_VERSION,
    generatedAt: now.toISOString(),
    summary: summarize(runs),
    runs,
  };
}

/** One <testsuite> per workflow, one <testcase> per run. */
export function toJUnitXml(runs: RunRecord[], options: ReportOptions): string {
  const byWorkflow = new Map<string, RunRecord[]>();
  for (const run of runs) byWorkflow.set(run.workflowName, [...(byWorkflow.get(run.workflowName) ?? []), run]);
  const total = summarize(runs);
  const suites = [...byWorkflow.entries()].map(([name, list]) => {
    const sum = summarize(list);
    const cases = list.map((run) => {
      const steps = run.steps.map((step) => stepLine(step, options)).join('\n');
      let body = '';
      if (run.status === 'failed' || run.status === 'interrupted') {
        body = `\n      <failure message="${xml(run.error ?? run.status)}" type="${run.status}">${xml(steps)}</failure>`;
      } else if (run.status === 'cancelled') {
        body = `\n      <skipped message="${xml(run.error ?? 'cancelled')}"/>`;
      }
      body += `\n      <system-out>${xml(steps)}</system-out>`;
      return `    <testcase classname="${xml(name)}" name="${xml(`${run.startedAt} (${run.trigger})`)}" time="${seconds(durationOf(run))}">${body}\n    </testcase>`;
    });
    return `  <testsuite name="${xml(name)}" tests="${sum.total}" failures="${sum.failed}" skipped="${sum.other}" time="${seconds(sum.durationMs)}">\n${cases.join('\n')}\n  </testsuite>`;
  });
  return `<?xml version="1.0" encoding="UTF-8"?>\n<testsuites name="${xml(options.title ?? 'BlockFlow')}" tests="${total.total}" failures="${total.failed}" time="${seconds(total.durationMs)}">\n${suites.join('\n')}\n</testsuites>\n`;
}

function html(text: string): string {
  return text.replace(/[<>&"]/g, (char) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' })[char] ?? char);
}

/** M5.1: a traced step's before/after pictures (box drawn over the after one), URL and network summary. */
function traceHtml(step: StepRecord, options: ReportOptions): string {
  const trace = step.trace;
  if (!trace) return '';
  const picture = (id: string | undefined, label: string, withBox: boolean) => {
    const src = id ? options.screenshots?.[id] : undefined;
    if (!src) return '';
    const { box, viewport } = trace;
    const pct = (value: number, of: number) => `${Math.max(0, Math.min(100, (value / of) * 100)).toFixed(2)}%`;
    const overlay = withBox && box && viewport && viewport.width > 0 && viewport.height > 0
      ? `<span class="box" style="left:${pct(box.x, viewport.width)};top:${pct(box.y, viewport.height)};width:${pct(box.width, viewport.width)};height:${pct(box.height, viewport.height)}"></span>`
      : '';
    return `<figure><figcaption>${label}</figcaption><div class="frame"><img src="${src}" alt="${label}">${overlay}</div></figure>`;
  };
  const pictures = picture(trace.before, 'Before', false) + picture(trace.after, 'After', true);
  const network = trace.network
    ? `<div class="meta">Network: ${trace.network.requests} requests${trace.network.failed ? `, ${trace.network.failed} failed` : ''}${trace.network.slowest?.length ? ` · slowest: ${trace.network.slowest.map((request) => html(`${request.method} ${request.url} ${request.ms} ms`)).join(', ')}` : ''}</div>`
    : '';
  const url = trace.url ? `<div class="meta">${html(trace.url)}</div>` : '';
  return pictures || network || url ? `<div class="trace">${pictures ? `<div class="pair">${pictures}</div>` : ''}${url}${network}</div>` : '';
}

/** A single HTML file, no external resources. */
export function toHtmlReport(runs: RunRecord[], options: ReportOptions): string {
  const sum = summarize(runs);
  const title = options.title ?? 'BlockFlow test report';
  const sections = runs.map((run) => {
    const rows = run.steps
      .map((step) => {
        const shot = step.screenshot ? options.screenshots?.[step.screenshot] : undefined;
        return `<tr class="${step.status}"><td>${html(step.status)}</td><td>${html(options.blockLabel(step.blockType))}</td><td>${step.durationMs ?? ''} ms</td><td>${step.code ? `<code>${html(step.code)}</code> ` : ''}${html(step.error ?? '')}${step.console?.length ? `<details><summary>Console (${step.console.length})</summary><pre>${step.console.map((entry) => html(`[${entry.level}] ${entry.text}${entry.url ? ` (${entry.url})` : ''}`)).join('\n')}</pre></details>` : ''}${shot ? `<br><img src="${shot}" alt="Screenshot">` : ''}${traceHtml(step, options)}</td></tr>`;
      })
      .join('');
    return `<section class="${run.status}"><h2><span class="badge ${run.status}">${html(run.status)}</span> ${html(run.workflowName)}</h2>
<p class="meta">${html(new Date(run.startedAt).toLocaleString())} · ${html(run.trigger)} · ${(durationOf(run) / 1000).toFixed(1)} s${run.mode?.trace ? ' · traced' : ''}${run.usedDebugger ? ' · Chromium debugger (CDP)' : ''}${run.error ? ` · <b>${html(run.error)}</b>` : ''}</p>
<table><thead><tr><th>Status</th><th>Block</th><th>Time</th><th>Details</th></tr></thead><tbody>${rows}</tbody></table></section>`;
  });
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${html(title)}</title>
<style>
body{font:14px/1.45 system-ui,sans-serif;margin:24px auto;max-width:1000px;padding:0 16px;color:#1b1e24;background:#f6f7f9}
h1{margin:0 0 4px}.meta{color:#6b7280;margin:4px 0 10px}section{background:#fff;border:1px solid #e2e5ea;border-radius:8px;padding:12px 16px;margin:14px 0}
section.failed,section.interrupted{border-left:5px solid #dc2626}section.passed{border-left:5px solid #16a34a}
h2{font-size:16px;margin:0}table{width:100%;border-collapse:collapse;font-size:13px}td,th{text-align:left;padding:4px 6px;border-top:1px solid #eee;vertical-align:top}
tr.failed td:first-child{color:#dc2626;font-weight:600}tr.passed td:first-child{color:#16a34a}tr.handled td:first-child{color:#d97706}
.badge{font-size:12px;padding:1px 8px;border-radius:999px;background:#eee}.badge.passed{background:#dcfce7;color:#166534}.badge.failed,.badge.interrupted{background:#fee2e2;color:#991b1b}
img{max-width:100%;margin-top:6px;border:1px solid #ddd;border-radius:4px}
.trace .pair{display:grid;grid-template-columns:1fr 1fr;gap:8px}.trace figure{margin:6px 0 0}.trace figcaption{font-size:11px;color:#6b7280}
.trace .frame{position:relative;line-height:0}.trace .frame img{width:100%;margin:0}.trace .box{position:absolute;box-sizing:border-box;border:2px solid #f59e0b;background:rgba(245,158,11,.18)}.totals span{margin-right:14px}
</style></head><body>
<h1>${html(title)}</h1>
<p class="meta totals"><span>${sum.total} runs</span><span style="color:#16a34a">${sum.passed} passed</span><span style="color:#dc2626">${sum.failed} failed</span><span>${sum.other} other</span><span>${(sum.durationMs / 1000).toFixed(1)} s</span></p>
${sections.join('\n')}
</body></html>
`;
}

// ---------- suites (M4.4) ----------

/** Version of the JSON suite report (`toSuiteJson`); same rules as {@link REPORT_SCHEMA_VERSION}. */
export const SUITE_REPORT_SCHEMA_VERSION = 1;
/** Where the suite report schema is published (generated by scripts/reportSchema.ts). */
export const SUITE_REPORT_SCHEMA_PATH = 'docs/guide/suite-report.schema.json';

/** The JSON suite report: the suite's outcome, counts and every run, in suite order. */
export interface JsonSuiteReport {
  $schema: string;
  schemaVersion: typeof SUITE_REPORT_SCHEMA_VERSION;
  generatedAt: string;
  suite: { id?: string; name: string; status: SuiteResult['status']; startedAt: string; finishedAt: string; skipped: string[] };
  summary: ReturnType<typeof suiteSummary>;
  runs: RunRecord[];
}

/** The JSON suite report of `result` (see {@link JsonSuiteReport}). `now` is the report time. */
export function toSuiteJson(result: SuiteResult, now: Date = new Date()): JsonSuiteReport {
  const suite: JsonSuiteReport['suite'] = { name: result.name, status: result.status, startedAt: result.startedAt, finishedAt: result.finishedAt, skipped: result.skipped };
  if (result.suiteId) suite.id = result.suiteId;
  return {
    $schema: `https://github.com/akib35/blockflow/${SUITE_REPORT_SCHEMA_PATH}`,
    schemaVersion: SUITE_REPORT_SCHEMA_VERSION,
    generatedAt: now.toISOString(),
    suite,
    summary: suiteSummary(result),
    runs: result.runs,
  };
}

/** One line naming why a failed run failed: `[code] Block: message` of its failing step, else the run's error. */
function failureMessage(run: RunRecord, options: ReportOptions): string {
  const step = failingStep(run);
  if (step?.error) return `${step.code ? `[${step.code}] ` : ''}${options.blockLabel(step.blockType)}: ${step.error}`;
  return run.error ?? run.status;
}

const SKIPPED_MESSAGE = 'Not run: an earlier workflow failed and the suite stops on failure.';

/**
 * One <testsuite> named after the suite, one <testcase> per workflow (classname = suite, name =
 * workflow). A run that did not pass is a <failure> (message = failing step's code and message, body =
 * every step); workflows not run because of stopOnFailure are <skipped/>.
 */
export function toSuiteJUnit(result: SuiteResult, options: ReportOptions): string {
  const sum = suiteSummary(result);
  const cases = result.runs.map((run) => {
    const steps = run.steps.map((step) => stepLine(step, options)).join('\n');
    let body = '';
    if (run.status !== 'passed') {
      const step = failingStep(run);
      body = `\n      <failure message="${xml(failureMessage(run, options))}" type="${xml(step?.code ?? run.status)}">${xml([run.error, steps].filter(Boolean).join('\n'))}</failure>`;
    }
    body += `\n      <system-out>${xml(steps)}</system-out>`;
    return `    <testcase classname="${xml(result.name)}" name="${xml(run.workflowName)}" time="${seconds(durationOf(run))}">${body}\n    </testcase>`;
  });
  for (const name of result.skipped) {
    cases.push(`    <testcase classname="${xml(result.name)}" name="${xml(name)}" time="0.000">\n      <skipped message="${xml(SKIPPED_MESSAGE)}"/>\n    </testcase>`);
  }
  const attrs = `tests="${sum.total}" failures="${sum.failed}" skipped="${sum.skipped}" time="${seconds(sum.durationMs)}"`;
  return `<?xml version="1.0" encoding="UTF-8"?>\n<testsuites name="${xml(options.title ?? result.name)}" ${attrs}>\n  <testsuite name="${xml(result.name)}" ${attrs} timestamp="${xml(result.startedAt)}">\n${cases.join('\n')}\n  </testsuite>\n</testsuites>\n`;
}

/** A self-contained HTML page: the suite's totals, then one section per workflow (skipped ones listed). */
export function toSuiteHtml(result: SuiteResult, options: ReportOptions): string {
  const sum = suiteSummary(result);
  const page = toHtmlReport(result.runs, { ...options, title: options.title ?? `Suite: ${result.name}` });
  const header = `<p class="meta totals"><span class="badge ${result.status}">${html(result.status)}</span> <span>${sum.total} workflows</span><span style="color:#16a34a">${sum.passed} passed</span><span style="color:#dc2626">${sum.failed} failed</span><span>${sum.skipped} skipped</span><span>${(sum.durationMs / 1000).toFixed(1)} s</span><span>${html(new Date(result.startedAt).toLocaleString())}</span></p>`;
  const skipped = result.skipped.length
    ? `\n<section class="skipped"><h2><span class="badge">skipped</span> ${result.skipped.length} workflow${result.skipped.length === 1 ? '' : 's'} not run</h2><p class="meta">${html(SKIPPED_MESSAGE)}</p><ul>${result.skipped.map((name) => `<li>${html(name)}</li>`).join('')}</ul></section>`
    : '';
  // toHtmlReport's own totals line counts runs; the suite header replaces it.
  // Function replacers: names may contain `$&` and the like.
  return page.replace(/<p class="meta totals">.*?<\/p>/, () => header).replace('\n</body></html>', () => `${skipped}\n</body></html>`);
}
